  function bfsD(G, s, d) { const A = nbrs(G, d), dist = Array(G.n).fill(Infinity); dist[s] = 0; const q = [s]; for (let h = 0; h < q.length; h++) for (const v of A[q[h]]) if (dist[v] === Infinity) { dist[v] = dist[q[h]] + 1; q.push(v); } return dist; }
  function comps(G, nodes = U.range(G.n), edges = G.edges) { const p = U.range(G.n), f = (x) => (p[x] === x ? x : (p[x] = f(p[x]))); edges.forEach((e) => (p[f(e.u)] = f(e.v))); const m = new Map(); nodes.forEach((v) => { const r = f(v); if (!m.has(r)) m.set(r, []); m.get(r).push(v); }); return [...m.values()]; }
  function dijkstra(G, s, d) { const A = adj(G, d), dist = Array(G.n).fill(Infinity), done = Array(G.n).fill(false); dist[s] = 0; for (;;) { let u = -1; for (let i = 0; i < G.n; i++) if (!done[i] && dist[i] < Infinity && (u < 0 || dist[i] < dist[u])) u = i; if (u < 0) break; done[u] = true; for (const { v, w } of A[u]) if (dist[u] + w < dist[v]) dist[v] = dist[u] + w; } return dist; }
  const connectedWith = (G, edges, nodes) => comps(G, nodes, edges).length === 1;
